<?php require_once __DIR__ . '/includes/check_admin.php'; ?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Homepage â€” Valluvam Admin</title><link rel="icon" href="../images/logo.png"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/sweetalert2@11/dist/sweetalert2.min.css"><link rel="stylesheet" href="assets/admin.css">
<style>.cms-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:16px}.cms-card{padding:18px}.cms-card h2{font-size:17px;margin:0 0 4px}.cms-fields{display:grid;gap:10px;margin-top:14px}.cms-fields label{font-size:12px;font-weight:700;color:#5d574d}.cms-fields textarea{min-height:76px;resize:vertical}.cms-inline{display:grid;grid-template-columns:1fr 1fr;gap:10px}.cms-products{max-height:200px;overflow:auto;border:1px solid #e7dfd1;border-radius:8px;padding:8px}.cms-products label{display:flex;gap:8px;align-items:center;padding:5px;font-weight:500;font-size:13px}.cms-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:14px}.cms-preview{width:100%;height:75vh;border:0;border-radius:8px}.cms-thumb{width:100%;max-height:120px;object-fit:cover;border-radius:7px;margin-top:6px}@media(max-width:600px){.cms-inline{grid-template-columns:1fr}}</style></head>
<body><a class="adm-skip-link" href="#adm-main-content">Skip to content</a><div class="adm-shell"><?php require __DIR__ . '/includes/sidebar.php'; ?><main class="adm-main" id="adm-main-content">
<div class="adm-topbar"><div><h1>Homepage</h1><div class="adm-sub">Manage the current homepage without changing products, customers, orders, or the admin design.</div></div><div><button class="adm-btn adm-btn-ghost" id="previewAll"><i class="fas fa-eye"></i> Preview</button> <button class="adm-btn adm-btn-primary" id="saveAll"><i class="fas fa-floppy-disk"></i> Save changes</button></div></div>
<div class="adm-card" style="margin-bottom:16px"><div class="adm-card-body"><strong>Content manager</strong><div class="adm-cell-sub">Each card maps to the live homepage. Disable hides a section; Restore returns it to the current website default. Product selections reference existing products only.</div></div></div><div id="cmsSections" class="cms-grid"><div class="adm-card"><div class="adm-card-body"><span class="adm-skel" style="width:100%;height:22px"></span></div></div></div>
</main></div><script src="https://code.jquery.com/jquery-3.6.0.min.js"></script><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script><script>
const sections=[['hero','Hero','Hero banner, headings, CTAs and trust content'],['categories','Shop by Category','Category management uses the existing Categories page'],['best_sellers','Best Sellers','Choose existing products and their display order'],['why','Why Valluvam','Cards and section copy'],['healthy','Healthy Choices','Choose existing products and their display order'],['did_you_know','Did You Know','Educational cards and copy'],['traditional','Traditional Foods','Choose existing products and their display order'],['story','From Tradition to Your Table','Story image and copy'],['gifting','Gifting & Combos','Campaign content and existing products'],['curated_combos','Curated Combos','Combo cards, links and images'],['everyday','Everyday Essentials','Choose existing products and their display order'],['trending','Trending Now','Choose existing products and their display order'],['reviews','Loved by Customers','Reviews remain managed through Reviews'],['marketplaces','Shop Valluvam Your Way','Marketplace cards and links'],['wholesale','Wholesale / Bulk Orders','B2B content and enquiry link'],['private_label','Build Your Own Food Brand','Private-label content'],['kitchen','From Our Kitchen','Articles and recipe cards'],['newsletter','Newsletter','Subscription copy; existing backend unchanged'],['final_cta','Final CTA','Final banner and CTAs'],['footer','Footer','Footer copy and links']];
const collectionKeys={best_sellers:'best_sellers',healthy:'healthy',traditional:'traditional',gifting:'gifting',everyday:'everyday',trending:'trending'};let content={sections:{},collections:{}},products=[];
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function defaults(key,i){return {enabled:true,order:i+1,heading:'',description:'',image:'',cta_text:'',cta_url:''}}
function render(){let html='';sections.forEach(([key,name,help],i)=>{let c=Object.assign(defaults(key,i),content.sections[key]||{}), coll=collectionKeys[key], selected=(content.collections[coll]||[]).map(Number);let picker=coll?`<label>Existing products (check to select; checked order is saved)</label><div class="cms-products">${products.map(p=>`<label><input type="checkbox" data-collection="${coll}" value="${p.id}" ${selected.includes(Number(p.id))?'checked':''}> ${esc(p.product_name)}</label>`).join('')||'<span class="adm-cell-sub">No products available.</span>'}</div>`:'';html+=`<section class="adm-card cms-card" data-key="${key}"><h2>${name}</h2><div class="adm-cell-sub">${help}</div><div class="cms-fields"><div class="cms-inline"><label>Display order<input class="adm-input cms-order" type="number" min="1" value="${c.order}"></label><label>Visibility<select class="adm-input cms-enabled"><option value="1" ${c.enabled?'selected':''}>Visible</option><option value="0" ${!c.enabled?'selected':''}>Hidden</option></select></label></div><label>Heading<input class="adm-input cms-heading" value="${esc(c.heading)}" placeholder="Keep current website heading"></label><label>Description<textarea class="adm-input cms-description" placeholder="Keep current website description">${esc(c.description)}</textarea></label><label>Image path<input class="adm-input cms-image" value="${esc(c.image)}" placeholder="images/... or upload a replacement"></label><input class="cms-file" type="file" accept="image/*">${c.image?`<img class="cms-thumb" src="../${esc(c.image)}" alt="Current image">`:''}<div class="cms-inline"><label>CTA text<input class="adm-input cms-cta-text" value="${esc(c.cta_text)}"></label><label>CTA URL<input class="adm-input cms-cta-url" value="${esc(c.cta_url)}"></label></div>${picker}</div><div class="cms-actions"><button class="adm-btn adm-btn-ghost cms-preview-btn"><i class="fas fa-eye"></i> Preview</button><button class="adm-btn adm-btn-ghost cms-restore"><i class="fas fa-rotate-left"></i> Restore default</button><button class="adm-btn adm-btn-ghost cms-hide"><i class="fas fa-trash"></i> ${c.enabled?'Hide':'Restore'}</button></div></section>`});$('#cmsSections').html(html)}
function gather(){let next={sections:{},collections:{}};$('.cms-card[data-key]').each(function(){let el=$(this),key=el.data('key');next.sections[key]={enabled:el.find('.cms-enabled').val()==='1',order:+el.find('.cms-order').val()||0,heading:el.find('.cms-heading').val().trim(),description:el.find('.cms-description').val().trim(),image:el.find('.cms-image').val().trim(),cta_text:el.find('.cms-cta-text').val().trim(),cta_url:el.find('.cms-cta-url').val().trim()}});$('.cms-products input:checked').each(function(){let key=$(this).data('collection');(next.collections[key]??=[]).push(+this.value)});return next}
function preview(){sessionStorage.setItem('valluvamHomepageCmsPreview',JSON.stringify(gather()));Swal.fire({title:'Homepage preview',width:'96%',html:'<iframe class="cms-preview" src="../index.php"></iframe>',showCloseButton:true,showConfirmButton:false})}
function upload(input){let file=input.files[0];if(!file)return;let card=$(input).closest('.cms-card'),fd=new FormData();fd.append('action','upload');fd.append('image',file);$.ajax({url:'homepage_api.php',type:'POST',data:fd,processData:false,contentType:false,dataType:'json'}).done(r=>{if(r.status==='success'){card.find('.cms-image').val(r.path);Swal.fire({toast:true,position:'top-end',icon:'success',title:'Image ready — save changes to publish',showConfirmButton:false,timer:1800})}else Swal.fire('Upload failed',r.message||'', 'error')}).fail(()=>Swal.fire('Upload failed','The image could not be uploaded.','error'))}
$(async function(){try{let response=await fetch('/admin/homepage_api.php?action=get',{credentials:'same-origin',cache:'no-store'}),c=await response.json();if(!response.ok||c.status!=='success')throw new Error(c.message||'content');content=c.content||{};try{let productResponse=await fetch('/admin/homepage_api.php?action=products',{credentials:'same-origin',cache:'no-store'}),p=await productResponse.json();products=p.status==='success'?p.products||[]:[]}catch(_){products=[]}render()}catch(e){$('#cmsSections').html('<div class="adm-error">Could not load homepage content: '+esc(e.message||'Please refresh and try again.')+'</div>')}$('#saveAll').on('click',function(){content=gather();$.post('/admin/homepage_api.php?action=save',{content:JSON.stringify(content)},r=>{if(r.status==='success')Swal.fire({icon:'success',title:'Changes saved successfully.',timer:1400,showConfirmButton:false});else Swal.fire('Could not save',r.message||'','error')},'json')});$('#previewAll').on('click',preview);$(document).on('click','.cms-preview-btn',preview).on('change','.cms-file',function(){upload(this)}).on('click','.cms-restore',function(){let key=$(this).closest('.cms-card').data('key');delete content.sections[key];if(collectionKeys[key])delete content.collections[collectionKeys[key]];render()}).on('click','.cms-hide',function(){let card=$(this).closest('.cms-card'),enabled=card.find('.cms-enabled');enabled.val(enabled.val()==='1'?'0':'1');$(this).text(enabled.val()==='1'?'Hide':'Restore')})});
</script></body></html>
